sed -i '' 's/import { GitCompare, ChevronLeft, Calendar } from '"'"'lucide-react'"'"';/import { GitCompare, ChevronLeft, Calendar, FileText, Download } from '"'"'lucide-react'"'"';\nimport { useState } from '"'"'react'"'"';\nimport { jsPDF } from '"'"'jspdf'"'"';\nimport { useToastContext } from '"'"'@\/components\/common\/ToastContext'"'"';/g' src/pages/Entities/EntityDetail.tsx

sed -i '' 's/const entity = entitiesData.find(e => e.id === id);/const entity = entitiesData.find(e => e.id === id);\n  const { showToast } = useToastContext();\n\n  const handleDownloadDossier = () => {\n    try {\n      const doc = new jsPDF();\n      doc.setFontSize(22);\n      doc.text(`${entity?.name} - Supervisory Dossier`, 20, 30);\n      doc.setFontSize(12);\n      doc.text(`Entity ID: ${entity?.id}`, 20, 45);\n      doc.text(`Sector: ${entity?.sector}`, 20, 55);\n      doc.text(`Risk Level: ${entity?.riskLevel}`, 20, 65);\n      doc.text(`Assessment Period: ${entity?.assessmentPeriod}`, 20, 75);\n      doc.text("--------------------------------------------------", 20, 85);\n      doc.text(`Total Alerts: ${formatNumber(entity?.alertCount || 0)}`, 20, 95);\n      doc.text(`Critical Alerts: ${formatNumber(entity?.criticalAlertCount || 0)}`, 20, 105);\n      doc.text(`Investigation Rate: ${entity?.investigationRate}%`, 20, 115);\n      \n      doc.text("--------------------------------------------------", 20, 135);\n      doc.text("Supervisory Findings Summary:", 20, 145);\n      \n      if (entityFindings.length > 0) {\n        let y = 155;\n        entityFindings.forEach(f => {\n          doc.setFontSize(10);\n          doc.text(`- ${f.title} (${f.severity})`, 25, y);\n          y += 10;\n        });\n      } else {\n        doc.setFontSize(10);\n        doc.text("No findings recorded.", 25, 155);\n      }\n\n      doc.save(`${entity?.id}_Dossier.pdf`);\n      showToast("Dossier downloaded successfully!");\n    } catch (e) {\n      console.error(e);\n      showToast("Failed to generate dossier.");\n    }\n  };\n/g' src/pages/Entities/EntityDetail.tsx

sed -i '' 's/<div className="flex flex-col items-end">/<div className="flex flex-col items-end space-y-4">\n          <button onClick={handleDownloadDossier} className="flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors shadow-sm">\n            <FileText className="w-4 h-4 mr-2" />\n            Export Dossier\n          <\/button>\n          <div className="flex flex-col items-end">/g' src/pages/Entities/EntityDetail.tsx

sed -i '' 's/<Badge variant={getRiskBadgeVariant(entity.riskLevel)} className="text-lg px-4 py-1">{entity.riskLevel}<\/Badge>\n        <\/div>/<Badge variant={getRiskBadgeVariant(entity.riskLevel)} className="text-lg px-4 py-1">{entity.riskLevel}<\/Badge>\n          <\/div>\n        <\/div>/g' src/pages/Entities/EntityDetail.tsx

